function(container, apiUrl, tables) {
  const contractListEl = container.querySelector('#contract-list');
  const detailPanelEl = container.querySelector('#detail-panel');
  const emptyStateEl = container.querySelector('#empty-state');
  const customerIdInput = container.querySelector('[data-testid="customer-id-input"]');
  const customerNameInput = container.querySelector('[data-testid="customer-name-input"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const resetBtn = container.querySelector('[data-testid="reset-button"]');
  const viewHistoryBtn = container.querySelector('[data-testid="view-history-button"]');
  const viewBillingBtn = container.querySelector('[data-testid="view-billing-button"]');

  let allContracts = [];
  let selectedContractId = null;

  // テーブルインデックス（tables 配列から推定）
  const contractTableIndex = tables.findIndex(t => t.tableName === '契約') || 0;
  const customerTableIndex = tables.findIndex(t => t.tableName === '顧客') || 1;

  // ステータスバッジクラスを返す
  function getStatusClass(status) {
    if (status.includes('契約済') || status.includes('有効')) return 'status-active';
    if (status.includes('提案') || status.includes('承認待')) return 'status-pending';
    if (status.includes('完了')) return 'status-completed';
    if (status.includes('終了')) return 'status-ended';
    return 'status-pending';
  }

  // 日付フォーマット
  function formatDate(dateStr) {
    if (!dateStr) return '-';
    const d = new Date(dateStr);
    return d.toLocaleDateString('ja-JP');
  }

  // 金額フォーマット
  function formatAmount(amount) {
    if (!amount) return '¥0';
    return '¥' + amount.toLocaleString('ja-JP');
  }

  // 契約一覧を描画
  function renderContractList(contracts) {
    contractListEl.innerHTML = '';
    if (contracts.length === 0) {
      contractListEl.innerHTML = '<div style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">該当する契約がありません</div>';
      return;
    }
    contracts.forEach(contract => {
      const item = document.createElement('div');
      item.className = 'contract-item';
      item.dataset.contractId = contract.id;
      item.innerHTML = `
        <p class="contract-item-title">${contract.contract_name || contract.contractName || '（名称未設定）'}</p>
        <p class="contract-item-meta">ID: ${contract.id.substring(0, 8)}...</p>
        <p class="contract-item-meta">期間: ${formatDate(contract.contract_start_date || contract.contractStartDate)} ～ ${formatDate(contract.contract_end_date || contract.contractEndDate)}</p>
        <p class="contract-item-meta">金額: ${formatAmount(contract.contract_amount || contract.contractAmount)}</p>
      `;
      item.addEventListener('click', () => selectContract(contract));
      contractListEl.appendChild(item);
    });
  }

  // 契約を選択
  function selectContract(contract) {
    selectedContractId = contract.id;

    // UI更新
    container.querySelectorAll('.contract-item').forEach(el => {
      el.classList.toggle('selected', el.dataset.contractId === contract.id);
    });

    // 詳細パネルを表示
    detailPanelEl.style.display = 'block';
    emptyStateEl.style.display = 'none';

    // 詳細情報を表示
    container.querySelector('#detail-contract-id').textContent = contract.id;
    container.querySelector('#detail-contract-name').textContent = contract.contract_name || contract.contractName || '-';

    const statusEl = container.querySelector('#detail-status');
    const status = contract.contract_status || contract.contractStatus || '-';
    statusEl.textContent = status;
    statusEl.className = 'status-badge ' + getStatusClass(status);

    container.querySelector('#detail-amount').textContent = formatAmount(contract.contract_amount || contract.contractAmount);
    container.querySelector('#detail-start-date').textContent = formatDate(contract.contract_start_date || contract.contractStartDate);
    container.querySelector('#detail-end-date').textContent = formatDate(contract.contract_end_date || contract.contractEndDate);
    container.querySelector('#detail-content').textContent = contract.contract_content || contract.contractContent || '（詳細なし）';

    // 割引基準を表示（ダミー実装：実際にはAPIから取得）
    renderDiscountInfo(contract);
  }

  // 割引基準情報を描画
  function renderDiscountInfo(contract) {
    const discountEl = container.querySelector('#discount-info');

    // 契約金額に基づく割引基準を計算（ダミーロジック）
    const amount = contract.contract_amount || contract.contractAmount || 0;
    let discountRate = 0;
    let discountReason = '';

    if (amount >= 10000000) {
      discountRate = 15;
      discountReason = '大口契約割引';
    } else if (amount >= 5000000) {
      discountRate = 10;
      discountReason = '中規模契約割引';
    } else if (amount >= 1000000) {
      discountRate = 5;
      discountReason = '標準契約割引';
    } else {
      discountRate = 0;
      discountReason = '割引対象外';
    }

    const discountAmount = Math.floor(amount * discountRate / 100);

    discountEl.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 12px;">
        <div>
          <span style="color: var(--text-muted); display: block; margin-bottom: 2px;">割引基準</span>
          <span style="color: var(--text); font-weight: 500;">${discountReason}</span>
        </div>
        <div>
          <span style="color: var(--text-muted); display: block; margin-bottom: 2px;">割引率</span>
          <span style="color: var(--primary); font-weight: 600;">${discountRate}%</span>
        </div>
        <div style="grid-column: 1 / -1;">
          <span style="color: var(--text-muted); display: block; margin-bottom: 2px;">割引額</span>
          <span style="color: var(--primary); font-weight: 600; font-size: 14px;">${formatAmount(discountAmount)}</span>
        </div>
      </div>
    `;
  }

  // 検索実行
  async function performSearch() {
    const customerId = customerIdInput.value.trim();
    const customerName = customerNameInput.value.trim();

    try {
      // 契約一覧を取得
      const contracts = await window.aivicApi.list(contractTableIndex);
      if (!contracts) {
        contractListEl.innerHTML = '<div style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">データ取得に失敗しました</div>';
        return;
      }

      // フィルタリング
      allContracts = contracts.filter(c => {
        const cId = c.customer_id || c.customerId || '';
        const cName = c.customer_name || c.customerName || '';

        const idMatch = !customerId || cId.includes(customerId);
        const nameMatch = !customerName || cName.includes(customerName);

        return idMatch && nameMatch;
      });

      renderContractList(allContracts);
      selectedContractId = null;
      detailPanelEl.style.display = 'none';
      emptyStateEl.style.display = 'block';
    } catch (err) {
      console.error('検索エラー:', err);
      contractListEl.innerHTML = '<div style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">エラーが発生しました</div>';
    }
  }

  // リセット
  function resetSearch() {
    customerIdInput.value = '';
    customerNameInput.value = '';
    contractListEl.innerHTML = '';
    detailPanelEl.style.display = 'none';
    emptyStateEl.style.display = 'block';
    selectedContractId = null;
  }

  // イベントリスナー
  searchBtn.addEventListener('click', performSearch);
  resetBtn.addEventListener('click', resetSearch);

  viewHistoryBtn.addEventListener('click', () => {
    if (selectedContractId) {
      window.showScreen('scr-1782623863124'); // 契約履歴・請求データ時系列照合
    }
  });

  viewBillingBtn.addEventListener('click', () => {
    if (selectedContractId) {
      window.showScreen('scr-1782623848853'); // 契約変更・請求照合ダッシュボード
    }
  });

  // 初期ロード（初期データを表示）
  if (tables[contractTableIndex] && tables[contractTableIndex].records) {
    allContracts = tables[contractTableIndex].records.slice(0, 10);
    renderContractList(allContracts);
  }
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const INVOICE_TABLE = 0;
  const INVOICE_DETAIL_TABLE = 1;
  const CONTRACT_TABLE = 2;
  const CUSTOMER_TABLE = 3;
  const APPROVAL_LOG_TABLE = 4;

  let currentInvoiceId = null;
  let currentInvoiceData = null;

  // 初期化: URL パラメータから請求IDを取得
  const urlParams = new URLSearchParams(window.location.search);
  const invoiceIdParam = urlParams.get('invoiceId');

  if (invoiceIdParam) {
    currentInvoiceId = invoiceIdParam;
    loadInvoiceData();
  } else {
    // デモ用: 最初の請求を表示
    loadFirstInvoice();
  }

  async function loadFirstInvoice() {
    const invoices = await window.aivicApi.list(INVOICE_TABLE);
    if (invoices && invoices.length > 0) {
      currentInvoiceId = invoices[0].id;
      loadInvoiceData();
    }
  }

  async function loadInvoiceData() {
    if (!currentInvoiceId) return;

    // 請求情報取得
    const invoices = await window.aivicApi.list(INVOICE_TABLE);
    currentInvoiceData = invoices.find(inv => inv.id === currentInvoiceId);

    if (!currentInvoiceData) {
      showError('請求情報が見つかりません');
      return;
    }

    // 顧客情報取得
    const customers = await window.aivicApi.list(CUSTOMER_TABLE);
    const customer = customers.find(c => c.id === currentInvoiceData.customerId);

    // 契約情報取得
    const contracts = await window.aivicApi.list(CONTRACT_TABLE);
    const contract = contracts.find(c => c.id === currentInvoiceData.contractId);

    // 請求明細取得
    const details = await window.aivicApi.list(INVOICE_DETAIL_TABLE);
    const invoiceDetails = details.filter(d => d.invoiceId === currentInvoiceId);

    // 承認ログ取得
    const logs = await window.aivicApi.list(APPROVAL_LOG_TABLE);
    const approvalLogs = logs.filter(l => l.invoiceId === currentInvoiceId);

    // ヘッダー情報を表示
    renderHeader(currentInvoiceData, customer, contract);

    // 明細テーブルを表示
    renderDetails(invoiceDetails);

    // 承認状態を表示
    renderApprovalStatus(currentInvoiceData, approvalLogs);
  }

  function renderHeader(invoice, customer, contract) {
    const formatDate = (date) => {
      if (!date) return '-';
      return new Date(date).toLocaleDateString('ja-JP');
    };

    const formatCurrency = (amount) => {
      if (amount === null || amount === undefined) return '¥0';
      return '¥' + Math.floor(amount).toLocaleString('ja-JP');
    };

    const periodStart = formatDate(invoice.invoicePeriodStartDate);
    const periodEnd = formatDate(invoice.invoicePeriodEndDate);

    container.querySelector('[data-testid="invoice-number"]').textContent = invoice.invoiceNumber || '-';
    container.querySelector('[data-testid="customer-name"]').textContent = customer?.customerName || '-';
    container.querySelector('[data-testid="contract-number"]').textContent = contract?.contractName || '-';
    container.querySelector('[data-testid="invoice-date"]').textContent = formatDate(invoice.invoiceDate);
    container.querySelector('[data-testid="invoice-period"]').textContent = `${periodStart} ～ ${periodEnd}`;
    container.querySelector('[data-testid="invoice-amount"]').textContent = formatCurrency(invoice.invoiceAmount);
    container.querySelector('[data-testid="tax-amount"]').textContent = formatCurrency(invoice.taxAmount);

    const totalAmount = (invoice.invoiceAmount || 0) + (invoice.taxAmount || 0);
    container.querySelector('[data-testid="total-amount"]').textContent = formatCurrency(totalAmount);
  }

  function renderDetails(details) {
    const tbody = container.querySelector('#invoice-details-tbody');
    tbody.innerHTML = '';

    if (details.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="4" style="padding: 20px; text-align: center; color: var(--text-muted);">明細がありません</td></tr>';
      return;
    }

    const formatCurrency = (amount) => {
      if (amount === null || amount === undefined) return '¥0';
      return '¥' + Math.floor(amount).toLocaleString('ja-JP');
    };

    details.forEach((detail, idx) => {
      const row = document.createElement('tr');
      row.style.borderBottom = '1px solid var(--border)';
      if (idx % 2 === 0) row.style.background = 'rgba(212, 175, 55, 0.02)';

      row.innerHTML = `
        <td style="padding: 10px 12px; border-right: 1px solid var(--border); color: var(--text);">${detail.chargeItemName || '-'}</td>
        <td style="padding: 10px 12px; text-align: right; border-right: 1px solid var(--border); color: var(--text);">${detail.quantity || 0}</td>
        <td style="padding: 10px 12px; text-align: right; border-right: 1px solid var(--border); color: var(--text);">${formatCurrency(detail.unitPrice)}</td>
        <td style="padding: 10px 12px; text-align: right; color: var(--primary); font-weight: 600;">${formatCurrency(detail.amount)}</td>
      `;
      tbody.appendChild(row);
    });
  }

  function renderApprovalStatus(invoice, logs) {
    const statusEl = container.querySelector('[data-testid="approval-status"]');
    const historyEl = container.querySelector('#approval-history');

    // ステータス表示
    const statusMap = {
      'pending': '未承認',
      'approved': '承認済',
      'rejected': '却下'
    };
    statusEl.textContent = statusMap[invoice.approvalStatus] || '未承認';
    statusEl.style.borderColor = invoice.approvalStatus === 'approved' ? 'var(--success)' : 
                                  invoice.approvalStatus === 'rejected' ? 'var(--error)' : 
                                  'var(--border)';

    // 承認履歴表示
    if (logs.length === 0) {
      historyEl.innerHTML = '<div style="padding: 8px; text-align: center; color: var(--text-muted);">履歴なし</div>';
    } else {
      historyEl.innerHTML = logs.map(log => {
        const date = new Date(log.createdAt).toLocaleDateString('ja-JP');
        const decision = log.decision === 'approve' ? '承認' : '却下';
        return `<div style="padding: 8px; border-bottom: 1px solid var(--border); font-size: 11px;">
          <div style="color: var(--text); font-weight: 500;">${decision} - ${date}</div>
          <div style="color: var(--text-muted); margin-top: 2px;">${log.comment || '（コメントなし）'}</div>
        </div>`;
      }).join('');
    }
  }

  // イベントリスナー
  container.querySelector('#submit-approval-btn').addEventListener('click', () => {
    const decision = container.querySelector('input[name="approval-decision"]:checked');
    if (!decision) {
      showError('承認/却下を選択してください');
      return;
    }

    const comment = container.querySelector('#approval-comment').value;
    const message = decision.value === 'approve' 
      ? `この請求を承認してもよろしいですか？\n請求番号: ${currentInvoiceData.invoiceNumber}`
      : `この請求を却下してもよろしいですか？\n請求番号: ${currentInvoiceData.invoiceNumber}`;

    showConfirmDialog(message, () => submitApproval(decision.value, comment));
  });

  container.querySelector('#cancel-approval-btn').addEventListener('click', () => {
    window.showScreen('scr-1782623848853'); // ダッシュボードへ
  });

  async function submitApproval(decision, comment) {
    try {
      // 請求ステータス更新
      const approvalStatus = decision === 'approve' ? 'approved' : 'rejected';
      await window.aivicApi.update(INVOICE_TABLE, currentInvoiceId, {
        approvalStatus: approvalStatus,
        verificationStatus: 'verified'
      });

      // 承認ログ記録
      await window.aivicApi.save(APPROVAL_LOG_TABLE, {
        invoiceId: currentInvoiceId,
        decision: decision,
        comment: comment,
        createdAt: new Date().toISOString()
      });

      showSuccess('承認が完了しました');
      setTimeout(() => {
        window.showScreen('scr-1782623848853'); // ダッシュボードへ
      }, 1500);
    } catch (err) {
      showError('承認処理に失敗しました');
    }
  }

  function showConfirmDialog(message, onConfirm) {
    const dialog = container.querySelector('#confirm-dialog');
    const messageEl = container.querySelector('#confirm-message');
    messageEl.textContent = message;
    dialog.style.display = 'flex';

    const okBtn = container.querySelector('#confirm-ok-btn');
    const cancelBtn = container.querySelector('#confirm-cancel-btn');

    const closeDialog = () => {
      dialog.style.display = 'none';
      okBtn.removeEventListener('click', handleOk);
      cancelBtn.removeEventListener('click', closeDialog);
    };

    const handleOk = () => {
      closeDialog();
      onConfirm();
    };

    okBtn.addEventListener('click', handleOk);
    cancelBtn.addEventListener('click', closeDialog);
    dialog.addEventListener('click', (e) => {
      if (e.target === dialog) closeDialog();
    });
  }

  function showSuccess(message) {
    const el = container.querySelector('#success-message');
    el.textContent = message;
    el.style.display = 'block';
    setTimeout(() => {
      el.style.display = 'none';
    }, 3000);
  }

  function showError(message) {
    const el = container.querySelector('#error-message');
    el.textContent = message;
    el.style.display = 'block';
    setTimeout(() => {
      el.style.display = 'none';
    }, 3000);
  }

  // ホバーエフェクト
  container.querySelector('#submit-approval-btn').addEventListener('mouseover', function() {
    this.style.background = 'var(--primary-hover)';
  });
  container.querySelector('#submit-approval-btn').addEventListener('mouseout', function() {
    this.style.background = 'var(--primary)';
  });

  container.querySelector('#cancel-approval-btn').addEventListener('mouseover', function() {
    this.style.background = 'rgba(212, 175, 55, 0.1)';
  });
  container.querySelector('#cancel-approval-btn').addEventListener('mouseout', function() {
    this.style.background = 'transparent';
  });
}
